/**
 * Parser and coding checks for the browser half, run in Node against real
 * .xlsx / .docx fixtures generated by make_fixtures.py.
 *
 * The client module is a browser bundle, so this harness supplies the loader
 * and a minimal React stub, then reads the functions through the __DC_TEST__
 * hook the module exposes when that global exists.
 */
import assert from 'node:assert/strict'
import fs from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const HERE = path.dirname(fileURLToPath(import.meta.url))
const FIXTURES = path.join(HERE, 'fixtures')

const loaded = { factory: null }
globalThis.window = {
  __ModuleLoader__: {
    load(definition) {
      loaded.factory = definition.factory
    }
  }
}
const harness = (globalThis.__DC_TEST__ = {})

class Component {
  constructor(props) {
    this.props = props
  }
  setState() {}
}

const React = {
  createElement: (type, props, ...children) => ({ type, props, children }),
  createContext: value => ({ Provider: 'Provider', value }),
  useContext: () => text => text,
  useState: value => [typeof value === 'function' ? value() : value, () => {}],
  useEffect() {},
  useMemo: fn => fn(),
  useRef: () => ({ current: null }),
  useCallback: fn => fn,
  useSyncExternalStore: (subscribe, get) => get(),
  Component
}

await import('../client.js')
const plugin = loaded.factory(() => React)
assert.ok(plugin && typeof plugin.apply === 'function', 'plugin exposes apply')
const api = harness.api
assert.ok(api, 'test hook populated')

async function file(name) {
  const buffer = await fs.readFile(path.join(FIXTURES, name))
  return {
    name,
    type: '',
    async arrayBuffer() {
      return buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength)
    },
    async text() {
      return buffer.toString('utf8')
    }
  }
}

const results = []
async function check(name, fn) {
  try {
    await fn()
    results.push({ ok: true, name })
    console.log('ok   ' + name)
  } catch (error) {
    results.push({ ok: false, name, error })
    console.log('FAIL ' + name + '\n     ' + (error && error.message ? error.message : error))
  }
}

/* ------------------------------------------------------------------ excel */

await check('xlsx: sheets and matrix', async () => {
  const parsed = await api.readFileMatrix(await file('questionnaire.xlsx'))
  assert.equal(parsed.kind, 'xlsx')
  assert.deepEqual(parsed.sheets.map(sheet => sheet.name), ['编码表', '问卷'])
  const data = parsed.sheets[1]
  assert.equal(data.matrix.length, 6)
  assert.deepEqual(data.matrix[0].slice(0, 4), ['编号', '姓名', '性别', '年龄'])
  assert.equal(data.matrix[1][2], '男')
})

await check('xlsx: codebook sheet detection', async () => {
  const parsed = await api.readFileMatrix(await file('questionnaire.xlsx'))
  const entries = api.detectCodebook(parsed.sheets[0].matrix)
  assert.equal(entries.length, 12)
  assert.equal(entries[0].variable, '学历')
  assert.equal(entries[0].code, '1')
  assert.equal(entries[0].label, '小学及以下')
})

await check('xlsx: dataset columns, kinds and codes', async () => {
  const parsed = await api.readFileMatrix(await file('questionnaire.xlsx'))
  const dataset = api.datasetFromMatrix('问卷', parsed.sheets[1].matrix, { headerRow: 0 })
  assert.equal(dataset.columns.length, 9)
  assert.equal(dataset.rows.length, 5)
  assert.equal(dataset.rows[0].id, '1')
  const byLabel = Object.fromEntries(dataset.columns.map(column => [column.label, column]))
  assert.equal(byLabel['性别'].kind, 'categorical')
  assert.equal(byLabel['年龄'].kind, 'number')
  assert.equal(byLabel['姓名'].kind, 'text')
  assert.equal(api.codeOf(byLabel['性别'], '男'), '1')
  assert.equal(api.codeOf(byLabel['性别'], '女'), '2')
  assert.equal(api.codeOf(byLabel['学历'], '本科'), '5')
  assert.equal(api.codeOf(byLabel['婚姻状况'], '离异'), '3')
  assert.equal(api.codeOf(byLabel['户口性质'], '农村'), '2')
  assert.equal(api.codeOf(byLabel['政治面貌'], '共青团员'), '2')
  assert.equal(api.codeOf(byLabel['民族'], '少数民族'), '2')
  assert.equal(api.codeOf(byLabel['是否独生'], '是'), '1')
  assert.equal(api.codeOf(byLabel['是否独生'], '否'), '2')
  assert.equal(api.codeOf(byLabel['年龄'], '23'), '23')
})

await check('xlsx: codebook overrides the built-in dictionary', async () => {
  const parsed = await api.readFileMatrix(await file('questionnaire.xlsx'))
  const dataset = api.datasetFromMatrix('问卷', parsed.sheets[1].matrix, { headerRow: 0 })
  const applied = api.applyCodebook(dataset.columns, api.detectCodebook(parsed.sheets[0].matrix))
  assert.ok(applied >= 2)
  const education = dataset.columns.find(column => column.label === '学历')
  assert.equal(api.codeOf(education, '硕士'), '6')
  assert.equal(education.coding.enabled, true)
})

await check('csv export: header and coded cells', async () => {
  const parsed = await api.readFileMatrix(await file('questionnaire.xlsx'))
  const dataset = api.datasetFromMatrix('问卷', parsed.sheets[1].matrix, { headerRow: 0 })
  const lines = api.datasetCsv(dataset).trim().split('\r\n')
  assert.equal(lines.length, 6)
  assert.deepEqual(lines[0].split(','), ['被试编号', '姓名', '性别', '年龄', '学历', '婚姻状况', '户口性质', '政治面貌', '民族', '是否独生'])
  assert.equal(lines[1], '1,张三,1,23,5,1,1,2,1,1')
  assert.equal(lines[3], '3,王五,1,35,7,3,1,1,1,1')
})

await check('codebook export lists value=code pairs', async () => {
  const dataset = api.templateDataset('core')
  const rows = api.codebookCsv(dataset).trim().split('\r\n')
  assert.deepEqual(rows[0].split(','), ['变量名', '标签', '类型', '编码', '缺失值'])
  const sex = rows.find(row => row.startsWith('sex,'))
  assert.ok(sex.includes('男=1; 女=2'), sex)
})

/* ------------------------------------------------------------------- word */

await check('docx: table becomes responses', async () => {
  const parsed = await api.readFileMatrix(await file('questionnaire-table.docx'))
  assert.equal(parsed.kind, 'docx')
  assert.equal(parsed.sheets.length, 1)
  const dataset = api.datasetFromMatrix('登记表', parsed.sheets[0].matrix, { headerRow: 0 })
  assert.equal(dataset.columns.length, 4)
  assert.equal(dataset.rows.length, 3)
  assert.equal(api.codeOf(dataset.columns[1], '女'), '2')
})

await check('docx: 标签：值 paragraphs become one response', async () => {
  const parsed = await api.readFileMatrix(await file('questionnaire-paragraphs.docx'))
  assert.equal(parsed.sheets.length, 0)
  assert.deepEqual(Object.keys(parsed.pairs), ['姓名', '性别', '年龄', '学历', '政治面貌', '户口性质'])
  const dataset = api.datasetFromPairs('纸质问卷', parsed.pairs)
  assert.equal(dataset.rows.length, 1)
  const byKey = Object.fromEntries(dataset.columns.map(column => [column.key, column]))
  assert.equal(dataset.rows[0].values.sex, '男')
  assert.equal(api.codeOf(byKey.education, '硕士'), '6')
  assert.equal(api.codeOf(byKey.hukou, '农村'), '2')
})

/* -------------------------------------------------------------------- csv */

await check('csv: quoted cells, delimiter and header detection', async () => {
  const rows = api.parseCsv('\ufeff编号,性别,年龄\n1,"女,其他",23\n2,男,25\n')
  assert.equal(rows.length, 3)
  assert.equal(rows[1][1], '女,其他')
  const matrix = [['被试信息表', '', ''], ['编号', '性别', '年龄'], ['1', '男', '23'], ['2', '女', '25']]
  assert.equal(api.detectHeaderRow(matrix), 1)
  const dataset = api.datasetFromMatrix('测试', matrix)
  assert.equal(dataset.columns.length, 2)
  assert.equal(dataset.rows.length, 2)
  assert.equal(dataset.rows[0].id, '1')
})

/* ---------------------------------------------------------------- coding */

await check('dictionary: label aliases and typed codes', async () => {
  assert.equal(api.matchDictByLabel('您的性别').id, 'sex')
  assert.equal(api.matchDictByLabel('文化程度').id, 'education')
  assert.equal(api.matchDictByLabel('姓名'), null)
  const sex = api.templateDataset('core').columns.find(column => column.key === 'sex')
  assert.equal(api.canonicalValue(sex, '2'), '女')
  assert.equal(api.canonicalValue(sex, '男'), '男')
  assert.equal(api.codeOf(sex, '2'), '2')
  const options = api.effectiveOptions(sex)
  assert.deepEqual(options.map(option => option.label + '=' + option.code), ['男=1', '女=2'])
})

await check('merge: append keeps columns and maps labels', async () => {
  const parsed = await api.readFileMatrix(await file('questionnaire.xlsx'))
  const base = api.datasetFromMatrix('问卷', parsed.sheets[1].matrix, { headerRow: 0 })
  const extra = api.datasetFromPairs('纸质问卷', (await api.readFileMatrix(await file('questionnaire-paragraphs.docx'))).pairs)
  const merged = api.mergeDatasets(base, extra)
  assert.equal(merged.rows.length, 6)
  assert.equal(merged.columns.length, 9)
  const sex = merged.columns.find(column => column.label === '性别')
  assert.equal(merged.rows[5].values[sex.key], '男')
  assert.equal(api.codeOf(sex, merged.rows[5].values[sex.key]), '1')
})

await check('json snapshot is flat and readable', async () => {
  const dataset = api.templateDataset('blank')
  dataset.rows.push({ id: '7', values: {} })
  const snapshot = JSON.parse(api.datasetJson(dataset))
  assert.equal(snapshot.rows[0].id, '7')
  assert.equal(snapshot.name, dataset.name)
})

/* ------------------------------------------- 被试基本信息收集表（2026-10-26） */

await check('form: every column of 基本信息收集表 finds its dictionary entry', async () => {
  const expected = {
    '性别': 'sex',
    '是否为右利手': 'handedness',
    '年龄': 'age',
    '出生日期': 'birthDate',
    '受教育年限': 'eduYears',
    '最高学历（包含在读）': 'eduLevel',
    '年级（若在读）': 'grade',
    '民族': 'ethnicity',
    '出生地（长期成长地）': 'birthPlace',
    '当前居住地': 'currentResidence',
    '婚姻状态': 'marital',
    '填表日期': 'fillDate'
  }
  for (const [label, id] of Object.entries(expected)) {
    const entry = api.matchDictByLabel(label)
    assert.ok(entry, 'no entry for ' + label)
    assert.equal(entry.id, id, label + ' -> ' + entry.id)
  }
  assert.equal(api.matchDictByLabel('学历').id, 'education')
  assert.equal(api.matchDictByLabel('文化程度').id, 'education')
  assert.equal(api.matchDictByLabel('被试编号'), null)
})

await check('form: option values map to the expected codes', async () => {
  const edu = api.matchDictByLabel('最高学历（包含在读）')
  assert.equal(api.matchDictValue(edu, '高中及以下'), '1')
  assert.equal(api.matchDictValue(edu, '本科'), '2')
  assert.equal(api.matchDictValue(edu, '硕士研究生'), '3')
  assert.equal(api.matchDictValue(edu, '博士研究生'), '4')

  const hand = api.matchDictByLabel('是否为右利手')
  assert.equal(api.matchDictValue(hand, '是'), '1')
  assert.equal(api.matchDictValue(hand, '否'), '2')

  const grade = api.matchDictByLabel('年级（若在读）')
  assert.equal(api.matchDictValue(grade, '大一'), '1')
  assert.equal(api.matchDictValue(grade, '研一'), '5')
  assert.equal(api.matchDictValue(grade, '大五'), '9')
  assert.equal(api.matchDictValue(grade, '博三'), '12')

  const marry = api.matchDictByLabel('婚姻状态')
  assert.equal(api.matchDictValue(marry, '单身'), '1')
  assert.equal(api.matchDictValue(marry, '已婚'), '2')
  assert.equal(api.matchDictValue(marry, '离异'), '3')
  assert.equal(api.matchDictValue(marry, '恋爱'), '6')
})

await check('form: 本实验基本信息表 template keeps column kinds', async () => {
  const dataset = api.templateDataset('study')
  assert.equal(dataset.columns.length, 12)
  const kinds = Object.fromEntries(dataset.columns.map(column => [column.dict, column.kind]))
  assert.equal(kinds.age, 'number')
  assert.equal(kinds.eduYears, 'number')
  assert.equal(kinds.birthDate, 'text')
  assert.equal(kinds.birthPlace, 'text')
  assert.equal(kinds.currentResidence, 'text')
  assert.equal(kinds.fillDate, 'text')
  assert.equal(kinds.sex, 'categorical')
  assert.equal(kinds.handedness, 'categorical')
})

/* ---------------------------------------------------------------- summary */

const failed = results.filter(result => !result.ok)
console.log('\n' + (results.length - failed.length) + '/' + results.length + ' checks passed')
if (failed.length) process.exitCode = 1
